// src/icons/brand/marks.json → src/icons/brandmarks.gen.ts: the brand marks the Connect screen shows
// (Claude, OpenAI, Cursor, VS Code, Gemini, PostgreSQL, MySQL, GitHub Copilot). The paths come from
// simple-icons (CC0 1.0); the marks belong to their owners (web/BRAND_MARKS.md). Generated so the
// colours live in one data file, like tokens (test/checks.test.ts allows hex only in tokens and
// *.gen.ts). --check fails when the generated file is stale.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const src = JSON.parse(readFileSync(root + 'src/icons/brand/marks.json', 'utf8'));
const check = process.argv.includes('--check');

const ids = Object.keys(src.marks).sort();
for (const id of ids) {
  const m = src.marks[id];
  if (!/^#[0-9A-F]{6}$/.test(m.hex) || typeof m.path !== 'string' || m.path.length < 20 || !m.title || !m.source || !m.license) {
    console.error(`brandmarks: ${id} is incomplete in marks.json`);
    process.exit(1);
  }
  if (/<|>|"|javascript:|url\(/i.test(m.path)) {
    console.error(`brandmarks: ${id}'s path holds something that isn't path data`);
    process.exit(1);
  }
}
const lines = ids.map((id) => {
  const m = src.marks[id];
  return `  ${JSON.stringify(id)}: { title: ${JSON.stringify(m.title)}, hex: ${JSON.stringify(m.hex)}, dark: ${m.dark ? 'true' : 'false'}, path: ${JSON.stringify(m.path)} },`;
});
const ts = `// generated by web/scripts/brandmarks.mjs from src/icons/brand/marks.json. Do not edit.
// Paths: simple-icons (CC0 1.0). The marks and names belong to their owners; see web/BRAND_MARKS.md.

export interface BrandMark { title: string; hex: string; dark: boolean; path: string }

export const BRAND_MARKS = {
${lines.join('\n')}
} as const satisfies Record<string, BrandMark>;

export type BrandMarkId = keyof typeof BRAND_MARKS;
`;
const out = root + 'src/icons/brandmarks.gen.ts';
const cur = existsSync(out) ? readFileSync(out, 'utf8') : '';
if (cur !== ts) {
  if (check) { console.error(`stale: web/src/icons/brandmarks.gen.ts`); process.exit(1); }
  writeFileSync(out, ts);
  console.log(`wrote web/src/icons/brandmarks.gen.ts (${ids.length} marks)`);
}
